package reverseproxy

import "testing"

func TestAihProbeRegistry(t *testing.T) {
	r := newStreamRegistry()
	r.addLive([]string{"a", "b"})
	r.addLive([]string{"a", "b"})
	s := &detachedStream{upstream: "b"}
	rm := r.add(s)
	defer rm()
	if o := r.removeLive([]string{"a", "b"}); len(o) != 0 {
		t.Fatalf("closed %d streams though b is still live", len(o))
	}
	if o := r.removeLive([]string{"a", "b"}); len(o) != 1 {
		t.Fatalf("got %d orphans, want 1", len(o))
	}
}

package reverseproxy

import (
	"encoding/json"
	"testing"

	"github.com/caddyserver/caddy/v2/caddyconfig/caddyfile"
)

func TestAihProbeStreamOptions(t *testing.T) {
	var h Handler
	if err := h.UnmarshalCaddyfile(caddyfile.NewTestDispenser(`reverse_proxy a:1 {
		stream_detached
	}`)); err != nil {
		t.Fatal(err)
	}
	var j Handler
	if err := json.Unmarshal([]byte(`{"stream_detached":true}`), &j); err != nil {
		t.Fatal(err)
	}
	if !h.StreamDetached || !j.StreamDetached {
		t.Fatal("not set")
	}
}

